//! 🧪️ Retained finite LIST option construction preserves every original raw child and partial owner.
use super::*;
#[test]
fn original_integer_list_copy_preserves_raw_words_and_rejects_mode_substitution_before_debit(){
 let word=format!("{}ä€", "-".repeat(63));let source=vec![DslValue::Object(vec![("kind".into(),DslValue::String("integer".into())),("value".into(),DslValue::String(word.clone()))])];let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());let mut output=None;
 for turn in 0..100000{let demand=copy.as_ref().unwrap().demands(&source,2,Mode::Integer).unwrap();assert_eq!(demand,copy.as_ref().unwrap().demands(&source,2,Mode::Integer).unwrap());if turn>0{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&source,2,Mode::Real,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,2,Mode::Integer,cx)).unwrap(){break;}assert!(turn<99999);}
 assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());let DslValue::Array(values)=output.as_ref().unwrap()else{panic!("explicit INTEGER words")};assert_eq!(values[0],source[0]);assert_eq!(values[1].get("kind").and_then(DslValue::as_str),Some("integer"));assert_eq!(values[1].get("value").and_then(DslValue::as_str),Some(""));close(&mut caller,&mut copy);let mut retirement=RetainedCloneClose::default();for turn in 0..100000{if output.is_none()&&retirement.is_empty(){break;}let demand=retirement.next_owner_demands::<DslValue>(output.is_some(),&None,4096).unwrap();caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if retirement.is_empty(){retirement.begin_granted(&mut output,grant)?.ok_or_else(invalid)}else{retirement.step_granted(grant)})?;Ok(())})).unwrap();assert!(turn<99999);}assert!(output.is_none()&&retirement.is_empty());caller.finish();
}
use semio_framework_plugin::app_testing::OriginalWorkFixture;
#[test]
fn original_collection_backing_is_independent_of_the_visible_sixteen_content_cap(){
 for mode in [Mode::Integer,Mode::Real]{let source=(0..20).map(|index|DslValue::Object(vec![("kind".into(),DslValue::String(if mode==Mode::Integer{"integer"}else{"real"}.into())),("value".into(),if mode==Mode::Integer{DslValue::String(index.to_string())}else{DslValue::Object(vec![("bits".into(),DslValue::String(index.to_string()))])})])).collect::<Vec<_>>();let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());let mut output=None;for turn in 0..100000{if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,source.len(),mode,cx)).unwrap(){break;}assert!(turn<99999);}assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());assert_eq!(output.as_ref(),Some(&DslValue::Array(source)));close(&mut caller,&mut copy);let mut close=RetainedCloneClose::default();for turn in 0..100000{if output.is_none()&&close.is_empty(){break;}let demand=close.next_owner_demands::<DslValue>(output.is_some(),&None,4096).unwrap();caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if close.is_empty(){close.begin_granted(&mut output,grant)?.ok_or_else(invalid)}else{close.step_granted(grant)})?;Ok(())})).unwrap();assert!(turn<99999);}assert!(output.is_none()&&close.is_empty());caller.finish();}
}
fn source()->Vec<DslValue>{vec![DslValue::Object(vec![("kind".into(),DslValue::String("real".into())),("value".into(),DslValue::Object(vec![("bits".into(),DslValue::String("a".repeat(63)+"€"+&"ä".repeat(40)))]))]) ]}
fn close(caller:&mut OriginalWorkFixture,copy:&mut Option<ListCopy>){let mut retirement=RetainedCloneClose::default();for turn in 0..100000{if copy.is_none()&&retirement.is_empty(){break;}let demand=retirement.next_owner_demands::<ListCopy>(copy.is_some(),&None,4096).unwrap();for axis in 0..5{let mut denied=OriginalWorkFixture::stock();match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(denied,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();semio_framework_job::close_original_retained_step(cx,demand,|grant|if retirement.is_empty(){retirement.begin_granted(copy,grant)?.ok_or_else(invalid)}else{retirement.step_granted(grant)})?;assert_eq!(before,cx.retained_progress());Ok(())})));answer.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if retirement.is_empty(){retirement.begin_granted(copy,grant)?.ok_or_else(invalid)}else{retirement.step_granted(grant)})?;Ok(())})).unwrap();assert!(turn<99999);}assert!(copy.is_none()&&retirement.is_empty());}
#[test]
fn original_list_copy_keeps_utf8_prefix_and_explicit_new_blank_members(){let source=source();let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());let mut output=None;for turn in 0..100000{let demand=copy.as_ref().unwrap().demands(&source,3,Mode::Real).unwrap();for axis in 0..6{let mut denied=OriginalWorkFixture::stock();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4=>denied.maximum_depth=0,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx)).unwrap(){break;}assert!(turn<99999);}assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());let DslValue::Array(values)=output.as_ref().unwrap()else{panic!("LIST option")};assert_eq!(values.len(),3);assert_eq!(values[0],source[0]);for value in &values[1..]{assert_eq!(value.get("value").and_then(|value|value.get("bits")).and_then(DslValue::as_str),Some(""));}close(&mut caller,&mut copy);let mut retirement=RetainedCloneClose::default();for _ in 0..100000{if output.is_none()&&retirement.is_empty(){break;}let demand=retirement.next_owner_demands::<DslValue>(output.is_some(),&None,4096).unwrap();caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if retirement.is_empty(){retirement.begin_granted(&mut output,grant)?.ok_or_else(invalid)}else{retirement.step_granted(grant)})?;Ok(())})).unwrap();}assert!(output.is_none()&&retirement.is_empty());caller.finish();}
#[test]
fn original_list_copy_retires_every_cancelled_partial_prefix(){let source=source();let mut total=None;for prefix in std::iter::once(None).chain((0..100000).map(Some)){if prefix.is_some_and(|prefix|total.is_some_and(|total|prefix>=total)){break;}let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());for turn in 0..100000{if prefix==Some(turn){caller.cancel().cancel_now();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx)).unwrap(){assert!(prefix.is_none());total=Some(turn+1);break;}assert!(turn<99999);}close(&mut caller,&mut copy);caller.finish();}assert!(total.is_some());}
#[test]
fn original_list_child_string_survives_refused_construction_posting(){let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());*copy.as_mut().unwrap().parts=Some(Parts{strings:Default::default(),member:None,bits:None,root:None,output:None});let physical=OriginalConstructionDemand{items:1,copy_bytes:4096,capacity_bytes:19,release_bytes:0,depth:1};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|construct_row_string(&mut copy.as_mut().unwrap().parts.as_mut().unwrap().strings[4],20,"original typed draft",physical,cx)));assert!(answer.is_err());assert_eq!(copy.as_ref().unwrap().parts.as_ref().unwrap().strings[4].as_deref(),Some("original typed draft"));assert!(heap.requested_bytes>=20);assert_eq!(heap.released_bytes,0);close(&mut caller,&mut copy);caller.finish();}
#[test]
fn original_list_copy_rejects_caller_array_or_target_substitution_before_progress(){let source=source();let mut caller=OriginalWorkFixture::new();let mut copy=Some(ListCopy::default());assert!(!caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx)).unwrap());let substitute=source.clone();for(actual,target)in[(&substitute,3),(&source,2)]{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(actual,target,Mode::Real,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let mut foreign=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(972),semio_framework_job::Generation(2));let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&source,3,Mode::Real,cx)));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.finish();close(&mut caller,&mut copy);caller.finish();}
